/* Community, Marketplace, Austeddit (Buzz), Shadow, DownTime + Gaming */
(function () {
  const { I, esc, av, member, hero, tabs, sectionHead, masthead, card, empty, seg, bar, statCard, modal, toast, register, ACTS, MENUS, D } = P;

  /* ───────────── Community ───────────── */
  const CT = [{ id: 'students', label: 'Student Directory', icon: 'users' }, { id: 'faculty', label: 'Faculty Directory', icon: 'graduation-cap' }, { id: 'alumni', label: 'Alumni Directory', icon: 'briefcase' }, { id: 'clubs', label: 'Clubs Hub', icon: 'flag' }];
  const FAC = [['Dr. A. K. M. Rahman', 'Professor', 'CSE'], ['Dr. Shamima Akter', 'Associate Professor', 'CSE'], ['Md. Tanvir Ahmed', 'Assistant Professor', 'EEE'], ['Farzana Haque', 'Lecturer', 'CSE'], ['Dr. Kamal Uddin', 'Professor', 'ME'], ['Nusrat Jahan', 'Lecturer', 'BBA']];
  function community(sub) {
    sub = sub || 'students'; let b;
    const filt = `<div class="row between wrap" style="margin-bottom:14px"><input class="input" placeholder="Search by name, ID, dept…" style="max-width:320px">${seg('cdept', ['All', 'CSE', 'EEE', 'ME', 'ARCH', 'BBA'], 'All')}</div>`;
    if (sub === 'students') b = `<div class="content-card">${sectionHead('users', 'Community', 'Student Directory', '8,400+ AUSTians')}${filt}<div class="grid g4 keep2">${D.members.map((m) => `<section class="card hoverable person" data-go="/members/${m.id}">${av(m.id, 56)}<b>${m.name}</b><span class="faint" style="font-size:11.5px">${m.dept} · Batch ${m.batch}</span><span class="chip ${m.role !== 'Student' ? 'amber' : ''}">${m.role}</span></section>`).join('')}</div></div>`;
    else if (sub === 'faculty') b = `<div class="content-card">${sectionHead('graduation-cap', 'Community', 'Faculty Directory', 'Rooms, emails & counselling hours')}${filt}<div class="list">${FAC.map(([n, r, d]) => `<div class="list-row"><span class="ic-tile">${I('user', 16)}</span><div class="grow"><div class="t">${n}</div><div class="s">${r} · ${d} · Room 7A1${n.length % 9}</div></div><button class="btn sm" data-act="toast" data-msg="Email copied">${I('mail', 13)}<span>Email</span></button><button class="btn sm" data-act="mentor">Request mentor</button></div>`).join('')}</div></div>`;
    else if (sub === 'alumni') b = `<div class="content-card">${sectionHead('briefcase', 'Community', 'Alumni Directory', 'Where AUSTians work now')}<div class="grid g3">${[['Riyad Hasan', 'Walton', 'R&D Engineer', 'm4'], ['Sadia Noor', 'Google', 'SWE II', 'm5'], ['Rakib Hossain', 'bKash', 'Product Manager', 'm2'], ['Tahmid Alam', 'Grameenphone', 'Network Eng.', 'm6'], ['Nabila Karim', 'BRAC', 'Analyst', 'm7'], ['Zarif Ahmed', 'Therap BD', 'Senior SWE', 'm3']].map(([n, c, r, id]) => `<section class="card hoverable" data-act="mentor"><div class="row">${av(id, 44, false)}<div><b>${n}</b><div class="faint" style="font-size:11.5px">${r}</div></div></div><div class="row between" style="margin-top:12px"><span class="chip">${I('building-2', 11)}${c}</span><span class="faint" style="font-size:11px">CSE '1${n.length % 9}</span></div></section>`).join('')}</div></div>`;
    else b = `<div class="content-card">${sectionHead('flag', 'Community', 'Clubs Hub', '30 clubs · fair registration open', `<button class="btn sm primary" data-act="toast" data-msg="Application form opened">${I('plus', 14)}<span>Start a club</span></button>`)}<div class="grid g3">${D.clubs.map((c, i) => `<section class="card"><div class="row"><span class="ic-tile">${I(c.ic, 18)}</span><div class="grow"><b>${c.n}</b><div class="faint" style="font-size:11.5px">${c.m} members</div></div></div><div class="row" style="margin-top:14px;justify-content:space-between"><div class="row" style="gap:0">${D.members.slice(i, i + 3).map((m) => `<span style="margin-right:-8px">${av(m.id, 26, false)}</span>`).join('')}</div><button class="btn sm ${i === 0 ? '' : 'primary'}" data-act="join">${i === 0 ? 'Joined' : 'Join'}</button></div></section>`).join('')}</div></div>`;
    return hero({ icon: 'users', eyebrow: 'People of AUST', a: 'Commu', b: 'nity', sub: 'Find students, faculty, alumni mentors and clubs.' }) + tabs('/community', CT, sub) + b;
  }
  ACTS.join = (el) => { const j = el.textContent === 'Join'; el.textContent = j ? 'Joined' : 'Join'; el.classList.toggle('primary', !j); toast(j ? 'Joined club' : 'Left club'); };
  ACTS.mentor = () => modal({ title: 'Request a mentor session', icon: 'user-plus', body: `<div class="field"><span class="label">Topic</span><select class="input"><option>Career advice</option><option>Thesis</option><option>Higher studies</option></select></div><div class="field"><span class="label">Message</span><textarea class="input" placeholder="Hi! I'd love 20 minutes to ask about…"></textarea></div>`, foot: `<button class="btn ghost" data-close>Cancel</button><button class="btn primary" data-save data-msg="Request sent">Send request</button>` });
  register({ path: '/community', title: 'Community', group: 'Social', icon: 'users', render: community });

  /* ───────────── Marketplace ───────────── */
  register({ path: '/marketplace', title: 'Marketplace', group: 'Social', icon: 'shopping-bag', render: (sub) => {
    const cat = { exchange: 'Exchange Kit', 'lost-found': 'Lost & Found', 'to-let': 'To-Let' }[sub];
    const list = D.listings.filter((l) => !cat || l.c === cat);
    return hero({ icon: 'shopping-bag', eyebrow: 'Buy · sell · find', a: 'Market', b: 'place', sub: 'Calculators, drafters, rooms near campus and lost & found.', side: `<button class="btn primary" data-act="sell">${I('plus', 15)}Post listing</button>` }) +
      tabs('/marketplace', [{ id: 'all', label: 'All', icon: 'layout-grid' }, { id: 'exchange', label: 'Exchange Kits', icon: 'repeat' }, { id: 'lost-found', label: 'Lost & Found', icon: 'search' }, { id: 'to-let', label: 'To-Let', icon: 'house' }], sub || 'all') +
      `<div class="grid g3">${list.map((l, i) => `<section class="card hoverable listing" data-act="listing" data-i="${D.listings.indexOf(l)}"><div class="thumb">${I(l.c === 'To-Let' ? 'house' : l.c === 'Lost & Found' ? 'search' : ['cpu', 'pencil', 'book-open', 'shirt'][i % 4], 30)}</div><div class="row between" style="margin-top:12px"><b>${l.t}</b><span class="num ok">${l.p ? '৳' + l.p.toLocaleString() : 'Free'}</span></div><div class="row between" style="margin-top:8px"><span class="chip">${l.c}</span><span class="faint" style="font-size:11px">${l.cond}</span></div></section>`).join('')}</div>`;
  } });
  ACTS.listing = (el) => { const l = D.listings[+el.dataset.i]; const m = member(l.by); modal({ title: l.t, sub: `${l.c} · ${l.cond}`, icon: 'shopping-bag', body: `<div class="thumb" style="height:180px">${I('image', 36)}</div><div class="row between"><span class="num ok" style="font-size:1.5rem">${l.p ? '৳' + l.p.toLocaleString() : 'Free'}</span><span class="chip green">Available</span></div><div class="row">${av(m.id, 36)}<div><b>${m.name}</b><div class="faint" style="font-size:11.5px">${m.dept} · responds in ~1h</div></div></div>`, foot: `<button class="btn" data-act="toast" data-msg="Saved">${I('heart', 14)}Save</button><button class="btn primary" data-go="/connectbox/c4">${I('message-square', 14)}Message seller</button>` }); };
  ACTS.sell = () => modal({ title: 'Post a listing', icon: 'tag', body: `<div class="field"><span class="label">Title</span><input class="input" placeholder="e.g. Casio fx-991EX"></div><div class="form-grid"><div class="field"><span class="label">Category</span><select class="input"><option>Exchange Kit</option><option>Lost & Found</option><option>To-Let</option></select></div><div class="field"><span class="label">Price</span><input class="input" placeholder="৳"></div></div><div class="empty" style="padding:18px"><span class="ic-tile">${I('image', 20)}</span><p>Add up to 4 photos</p></div>`, foot: `<button class="btn ghost" data-close>Cancel</button><button class="btn primary" data-save data-msg="Listing posted">Post</button>` });

  /* ───────────── Austeddit (Buzz) ───────────── */
  const SUBS = ['general', 'academic', 'confession', 'campus', 'memes'];
  register({ path: '/austeddit', title: 'Austeddit', group: 'Social', icon: 'message-circle', nav: '/shadow', render: (sub) => buzz(sub) });
  function buzz(sub, embedded) {
    const posts = D.posts.filter((p) => !sub || sub === 'all' || p.sub === sub);
    const feed = `<div class="main-grid"><div class="stack"><section class="card row" style="padding:12px 14px">${av('me', 36, false)}<div class="input" style="display:flex;align-items:center;cursor:text;color:var(--text-tertiary)" data-act="new-post">Share something with AUST…</div><button class="btn primary" data-act="new-post">${I('plus', 14)}Post</button></section>
      <div class="row between">${seg('sort', ['Hot', 'New', 'Top'], 'Hot')}</div>
      ${posts.length ? posts.map((p) => `<section class="card post"><div class="votes"><button class="icon-btn" data-act="vote" data-d="1">${I('arrow-up', 17)}</button><b class="num">${p.up}</b><button class="icon-btn" data-act="vote" data-d="-1">${I('arrow-down', 17)}</button></div><div style="min-width:0;flex:1"><div class="row faint" style="font-size:11.5px">${av(p.by, 20, false)}<b style="color:var(--text-secondary)">r/${p.sub}</b>· ${member(p.by).name} · ${p.time}</div><h3 style="margin:8px 0 4px;font-size:15px">${esc(p.title)}</h3>${p.body ? `<p class="muted" style="margin:0;font-size:13px;line-height:1.5">${esc(p.body)}</p>` : `<div class="thumb" style="height:160px;margin-top:8px">${I('image', 30)}</div>`}<div class="row" style="margin-top:10px;gap:4px"><button class="btn sm ghost" data-act="comments">${I('message-circle', 14)}${p.cm}</button><button class="btn sm ghost" data-act="toast" data-msg="Link copied">${I('share-2', 14)}Share</button><button class="btn sm ghost" data-act="toast" data-msg="Saved">${I('bookmark', 14)}Save</button></div></div></section>`).join('') : empty('message-circle', 'No posts here yet', 'Start the conversation in this community.', `<button class="btn sm primary" data-act="new-post">Create post</button>`)}</div>
      <div class="stack">${card('Communities', 'hash', `<div class="list">${SUBS.map((s) => `<a class="list-row" data-go="/austeddit/${s}" style="cursor:pointer"><span class="ic-tile">${I('hash', 14)}</span><div class="grow t">r/${s}</div><span class="faint" style="font-size:11px">${(s.length * 431).toLocaleString()}</span></a>`).join('')}</div>`)}${card('Rules', 'shield-check', `<ol class="muted" style="margin:0;padding-left:18px;font-size:12.5px;line-height:1.8"><li>Be kind to fellow AUSTians</li><li>No personal info in confessions</li><li>Tag spoilers & exam leaks are banned</li></ol>`)}</div></div>`;
    if (embedded) return feed;
    return masthead({ icon: 'message-circle', over: 'Shadow', title: 'Austeddit', sub: 'The AUST forum — anonymous where it matters', stats: [['Posts today', '148'], ['Online', '612']] }) + tabs('/austeddit', [{ id: 'all', label: 'All', icon: 'flame' }, ...SUBS.map((s) => ({ id: s, label: s[0].toUpperCase() + s.slice(1), icon: { general: 'message-circle', academic: 'graduation-cap', confession: 'heart', campus: 'school', memes: 'smile' }[s] }))], sub || 'all') + feed;
  }
  ACTS.vote = (el) => { const b = el.parentElement.querySelector('b'); const on = el.classList.toggle('voted'); b.textContent = +b.textContent + (on ? +el.dataset.d : -el.dataset.d); el.style.color = on ? (el.dataset.d > 0 ? 'var(--accent-amber)' : 'var(--accent-rose)') : ''; };
  ACTS['new-post'] = () => modal({ title: 'Create post', icon: 'square-pen', body: `<div class="field"><span class="label">Community</span><select class="input">${SUBS.map((s) => `<option>r/${s}</option>`)}</select></div><div class="field"><span class="label">Title</span><input class="input" placeholder="An interesting title"></div><div class="field"><span class="label">Body</span><textarea class="input" placeholder="Text (optional)"></textarea></div><div class="row">${P.toggles([['Post anonymously', false]])}</div>`, foot: `<button class="btn ghost" data-close>Cancel</button><button class="btn primary" data-save data-msg="Posted to Austeddit">Post</button>` });
  ACTS.comments = () => modal({ title: 'Comments', icon: 'message-circle', wide: true, body: `${[['m6', 'Neso Academy er OS playlist ta best.', 34], ['m1', 'Galvin er ch 5 + slides is enough for mid.', 21], ['m8', 'Saved! thanks 🙏', 4]].map(([id, t, u]) => `<div class="row" style="align-items:flex-start">${av(id, 32)}<div><div style="font-size:12px"><b>${member(id).name}</b> <span class="faint">· 2h</span></div><div style="font-size:13px;margin-top:3px">${t}</div><div class="row faint" style="font-size:11px;margin-top:4px">${I('arrow-up', 12)}${u} · Reply</div></div></div>`).join('')}<div class="row"><input class="input" placeholder="Add a comment…"><button class="btn primary" data-act="toast" data-msg="Comment added">${I('send', 14)}</button></div>`, foot: false });

  /* ───────────── Shadow ───────────── */
  const ST = [{ id: 'reviews', label: 'Course Reviews', icon: 'star' }, { id: 'chat', label: 'Shadow Chat', icon: 'moon' }, { id: 'buzz', label: 'Buzz', icon: 'message-circle' }, { id: 'roast-cv', label: 'Roast CV', icon: 'flame' }];
  register({ path: '/shadow', title: 'Shadow', group: 'Social', icon: 'moon', render: (sub) => {
    sub = sub || 'reviews'; let b;
    if (sub === 'reviews') b = `<div class="grid g2">${D.courses.slice(0, 4).map((c, i) => `<section class="card"><div class="row between"><div><b>${c.code}</b><div class="faint" style="font-size:12px">${c.name}</div></div><div class="stars">${[1, 2, 3, 4, 5].map((s) => `<span class="${s <= 4 - (i % 2) ? 'on' : ''}" data-act="star">${I('star', 15)}</span>`).join('')}</div></div><div class="dashed"></div><p class="muted" style="margin:0;font-size:12.5px;line-height:1.55">“${['Teacher explains really well, quizzes are fair.', 'Lots of theory — start early before mids.', 'Project heavy but super practical.', 'Grading is strict, attend every class.'][i]}”</p><div class="row" style="margin-top:10px"><span class="chip">Difficulty ${3 + (i % 2)}/5</span><span class="chip green">Workload OK</span></div></section>`).join('')}</div>`;
    else if (sub === 'chat') b = `<section class="card shadow-chat"><div class="row between" style="margin-bottom:12px"><div class="row"><span class="ic-tile">${I('moon', 16)}</span><div><b>Anonymous room</b><div class="faint" style="font-size:11px">Names hidden · messages vanish in 24h</div></div></div><span class="chip green">48 online</span></div><div class="msgs" id="msgs" style="height:320px;border:1px solid var(--border-secondary);border-radius:var(--radius-md)">${[['Owl #21', 'Kal OS quiz cancel hobe naki?'], ['Fox #08', 'Sir to bollo hobe 😭'], ['me', 'Chapter 5 porlei hobe I think']].map(([n, t]) => `<div class="msg ${n === 'me' ? 'me' : ''}">${n !== 'me' ? `<b style="font-size:11px;display:block;color:var(--accent-amber)">${n}</b>` : ''}${t}</div>`).join('')}</div><div class="composer" style="padding:12px 0 0;border:0"><input class="input" id="cmp" placeholder="Say something anonymously…" data-enter="send" style="border-radius:var(--radius-full)"><button class="btn primary" data-act="send" style="width:38px;padding:0">${I('send', 16)}</button></div></section>`;
    else if (sub === 'buzz') b = buzz('all', true);
    else b = roast();
    return hero({ icon: 'moon', eyebrow: 'Say it in the shadows', a: 'Sha', b: 'dow', sub: 'Honest course reviews, anonymous chat, Buzz and CV roasts.' }) + tabs('/shadow', ST, sub) + b;
  } });
  ACTS.star = (el) => { const all = [...el.parentElement.children]; const n = all.indexOf(el); all.forEach((s, i) => s.classList.toggle('on', i <= n)); toast(`Rated ${n + 1}/5`); };
  function roast() {
    return `<div class="grid g2"><section class="card">${empty('upload', 'Drop your CV', 'PDF up to 5 MB. We roast it, then help fix it.', `<button class="btn primary sm" data-act="roast-go">${I('flame', 14)}Roast my CV</button>`)}</section><section class="card" id="roast">${empty('flame', 'Waiting for a victim', 'Your roast and score appear here.')}</section></div>`;
  }
  ACTS['roast-go'] = () => { const r = document.getElementById('roast'); r.innerHTML = `<div class="card-h"><h3>${I('flame', 16)}The roast</h3><div class="r"><span class="num ok" style="font-size:1.6rem">62</span><span class="faint">/100</span></div></div><div class="list">${[['"Proficient in MS Word" — in 2026? Bold.', 'rose'], ['3 projects, all named "Project".', 'rose'], ['Solid CF rating — lead with that!', 'green'], ['Add links to GitHub & live demos.', 'amber']].map(([t, c]) => `<div class="list-row"><span class="ic-tile ${c}">${I(c === 'green' ? 'thumbs-up' : c === 'amber' ? 'lightbulb' : 'flame', 14)}</span><div class="grow t" style="white-space:normal;font-weight:500">${t}</div></div>`).join('')}</div>`; r.animate([{ opacity: 0 }, { opacity: 1 }], 300); };
  register({ path: '/roast-cv', title: 'Roast CV', group: 'Social', icon: 'flame', nav: '/shadow', hidden: true, render: () => masthead({ icon: 'flame', over: 'Shadow', title: 'Roast CV', sub: 'Brutal feedback, kindly delivered', stats: [['Roasted', '1.2k'], ['Avg score', '58']] }) + roast() });

  /* ───────────── DownTime ───────────── */
  const DT = [{ id: 'organizing', label: 'Organizing Area', icon: 'layout-grid' }, { id: 'media', label: 'Media Tracker', icon: 'film' }, { id: 'rumour', label: 'Rumour or Real', icon: 'info' }, { id: 'trivia', label: 'Trivia', icon: 'brain' }, { id: 'gaming', label: 'Gaming Zone', icon: 'gamepad-2' }];
  let triviaQ = 0;
  const TRIVIA = [['Which year was AUST founded?', ['1995', '1999', '2001', '1992'], 0], ['Which floor is the AUST library on?', ['2nd', '4th', 'Ground', '6th'], 1], ['How many departments does AUST have?', ['6', '8', '10', '12'], 2]];
  register({ path: '/downtime', title: 'DownTime', group: 'Fun', icon: 'coffee', render: (sub) => {
    sub = sub || 'organizing'; const t = DT.find((x) => x.id === sub); let b;
    if (sub === 'organizing') b = `<div class="pinboard">${[['Group study — OS mid', 'Sat 4pm · Library 2F', 'm1'], ['Futsal Friday ⚽', '6 more players needed', 'm2'], ['Iftar party planning', 'Bring ideas!', 'm7'], ['Hackathon team?', 'Need 1 designer', 'm3']].map(([a, s, id], i) => `<div class="sticky s${i % 4}" data-act="toast" data-msg="Joined: ${a}"><b>${a}</b><span>${s}</span><div class="row" style="margin-top:auto">${av(id, 22, false)}<span style="font-size:11px">${member(id).name.split(' ')[0]}</span><span class="chip" style="margin-left:auto">${3 + i} going</span></div></div>`).join('')}<div class="sticky add" data-act="pin">${I('plus', 22)}<span>Pin a note</span></div></div>`;
    else if (sub === 'media') b = `<div class="grid g4 keep2">${[['Dune: Part Two', 'Movie', 'Watched', 5], ['Shogun', 'Series', 'Watching', 4], ['Attack on Titan', 'Anime', 'Watched', 5], ['Atomic Habits', 'Book', 'Reading', 4]].map(([n, k, s, r]) => `<section class="card"><div class="poster">${I(k === 'Book' ? 'book-open' : 'film', 28)}</div><b style="display:block;margin-top:10px">${n}</b><div class="row between" style="margin-top:6px"><span class="chip">${k}</span><span class="chip ${s === 'Watched' ? 'green' : 'amber'}">${s}</span></div></section>`).join('')}</div>`;
    else if (sub === 'rumour') b = `<div class="grid g2">${[['Mid-terms are being postponed by a week', 62], ['New AC in all 7th floor rooms', 81]].map(([r, p]) => `<section class="card"><span class="label">Rumour</span><h3 style="margin:6px 0 14px;font-size:15px">${r}</h3><div class="row"><button class="btn" style="flex:1" data-act="toast" data-msg="Voted Real">${I('check', 14)}Real</button><button class="btn" style="flex:1" data-act="toast" data-msg="Voted Fake">${I('x', 14)}Fake</button></div><div style="margin-top:12px">${bar(p)}</div><div class="row between faint" style="font-size:11px;margin-top:5px"><span>${p}% real</span><span>${100 - p}% fake</span></div></section>`).join('')}</div>`;
    else if (sub === 'trivia') { const [q, opts] = TRIVIA[triviaQ % 3]; b = `<section class="card trivia"><div class="row between"><span class="label">Question ${triviaQ % 3 + 1} / 3</span><span class="chip amber">${I('timer', 12)}0:15</span></div><h2 style="margin:12px 0 18px">${q}</h2><div class="grid g2">${opts.map((o, i) => `<button class="btn tv-opt" data-act="answer" data-i="${i}" style="height:48px;justify-content:flex-start">${String.fromCharCode(65 + i)}. ${o}</button>`).join('')}</div></section>`; }
    else b = `<div class="grid g3">${[['Ludo King', 'dice-5', 12], ['Chess Arena', 'swords', 8], ['Scribble', 'pencil', 21], ['Codenames', 'brain', 6], ['Valorant LFG', 'gamepad-2', 34], ['Trivia Royale', 'trophy', 15]].map(([n, ic, o]) => `<section class="card hoverable" data-go="/gaming/room/${n.toLowerCase().replace(/ /g, '-')}"><div class="poster">${I(ic, 30)}</div><div class="row between" style="margin-top:12px"><b>${n}</b><span class="chip green">${o} online</span></div></section>`).join('')}</div>`;
    return hero({ icon: 'coffee', eyebrow: 'Take a break', a: 'Down', b: 'Time', sub: 'Organize, debate rumours, test trivia, and game with fellow AUSTians.' }) + tabs('/downtime', DT, sub) + `<div class="content-card">${sectionHead(t.icon, 'DownTime', t.label, { organizing: 'Pinboard & group planning', media: 'Movies, series, anime & books', rumour: 'Vote: real or fake?', trivia: 'AUST trivia — 3 questions', gaming: 'Rooms, events & LFG' }[sub])}${b}</div>`;
  } });
  ACTS.answer = (el) => { const ok = +el.dataset.i === TRIVIA[triviaQ % 3][2]; el.style.background = ok ? 'var(--accent-emerald-glow)' : 'var(--accent-rose-glow)'; el.style.borderColor = ok ? 'var(--accent-emerald)' : 'var(--accent-rose)'; toast(ok ? 'Correct! +10 pts' : 'Not quite!', ok ? 'circle-check' : 'x'); setTimeout(() => { triviaQ++; P.render(); }, 900); };
  ACTS.pin = () => modal({ title: 'Pin a note', icon: 'pin', body: `<div class="field"><span class="label">Title</span><input class="input" placeholder="What's the plan?"></div><div class="field"><span class="label">Details</span><input class="input" placeholder="When & where"></div><div class="field"><span class="label">Colour</span>${seg('pc', ['Amber', 'Rose', 'Teal', 'Green'], 'Amber')}</div>`, foot: `<button class="btn ghost" data-close>Cancel</button><button class="btn primary" data-save data-msg="Pinned to board">Pin it</button>` });
  register({ path: '/gaming', title: 'Game Room', group: 'Fun', icon: 'gamepad-2', nav: '/downtime', hidden: true, render: (sub) => {
    const name = (sub.split('/')[1] || 'ludo-king').replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
    return masthead({ icon: 'gamepad-2', over: 'Gaming Zone', title: name, sub: 'Room #4821 · casual', stats: [['Players', '3/4'], ['Ping', '24ms']], nav: `<button class="btn sm" data-go="/downtime/gaming">${I('arrow-left', 14)}Leave</button>` }) +
      `<div class="main-grid"><section class="card"><div class="board">${Array.from({ length: 64 }, (_, i) => `<i class="${(i + (i >> 3)) % 2 ? 'dk' : ''}"></i>`).join('')}</div><div class="row" style="justify-content:center;margin-top:14px"><button class="btn primary" data-act="toast" data-msg="You rolled a 6! 🎲">${I('dice-5', 15)}Roll</button></div></section><div class="stack">${card('Players', 'users', `<div class="list">${D.members.slice(0, 3).map((m, i) => `<div class="list-row">${av(m.id, 32)}<div class="grow t">${m.name}</div>${i === 0 ? '<span class="chip amber">Turn</span>' : ''}</div>`).join('')}<div class="list-row faint">${I('user-plus', 16)}Waiting for player…</div></div>`)}${card('Room chat', 'message-square', `<div class="faint" style="font-size:12.5px;line-height:1.8"><b style="color:var(--text-primary)">Nadia:</b> gg 😂<br><b style="color:var(--text-primary)">Farhan:</b> ek round aro</div><input class="input" style="margin-top:10px" placeholder="Message…">`)}</div></div>`;
  } });
})();
